/* global globalThis */

/**
 * The recovery code — MTC-FCS-035.
 * ============================================================================
 * The edge case: somebody pays, mistypes their email address, and can never
 * log in. We cannot find them by the address (it is wrong) and they cannot
 * tell us the one we hold (they do not know what they typed). Stripe knows
 * about the payment, but searching for it needs something they can tell us.
 *
 * So a code is generated at checkout, shown on the success screen, and written
 * into the Stripe subscription's metadata. One thing they can read out, and one
 * lookup that finds the payment without knowing any email address at all.
 *
 * ── WHAT IT IS AND IS NOT ──────────────────────────────────────────────────
 * It is an identifier, not a password. Knowing one does not let anybody sign
 * in, change an email or see a card — it lets a person at our end FIND a
 * payment, and every action after that is taken by us. That is why 40 bits is
 * enough here and would not be if it were a credential.
 *
 * ── THE ALPHABET AVOIDS EVERY LOOKALIKE ────────────────────────────────────
 * No 0/O, no 1/I/L, no U (which becomes V in handwriting). This code gets read
 * down a phone line and copied off a screenshot, and every ambiguous character
 * is a support call about a code that "does not work".
 *
 * ── UNIFORM, NOT MODULO-BIASED ─────────────────────────────────────────────
 * Random bytes are rejected rather than folded with `%`, which would make the
 * first two letters of the alphabet slightly likelier than the rest. It costs
 * nothing here and it is the difference between 40 bits and "about 40 bits".
 *
 * ── WEB CRYPTO, NOT node:crypto ────────────────────────────────────────────
 * `globalThis.crypto.getRandomValues` exists in Node 18+ and in every browser.
 * Importing node's `crypto` here would be the same code and would also break
 * the build, because the success screen imports RECOVERY_NOTE from this file
 * and webpack does not polyfill node builtins. One module either side beats
 * two modules that have to be kept in step.
 */

const ALPHABET = "23456789ABCDEFGHJKMNPQRSTVWXYZ"
const GROUPS = 2
const PER_GROUP = 4

/** One character, uniformly. */
function pick() {
  // 256 is not a multiple of 30, so the top of the byte range is discarded
  // rather than wrapped.
  const limit = 256 - (256 % ALPHABET.length)
  const buffer = new Uint8Array(1)
  for (;;) {
    globalThis.crypto.getRandomValues(buffer)
    if (buffer[0] < limit) return ALPHABET[buffer[0] % ALPHABET.length]
  }
}

/**
 * A new code, e.g. `FCS-7K2M-93QX`.
 *
 * The prefix is cosmetic — it makes the code recognisable in an inbox, a
 * screenshot or a Stripe dashboard — and is ignored when reading one back.
 */
export function makeRecoveryCode(prefix = "FCS") {
  const groups = []
  for (let g = 0; g < GROUPS; g++) {
    let group = ""
    for (let i = 0; i < PER_GROUP; i++) group += pick()
    groups.push(group)
  }
  return `${prefix}-${groups.join("-")}`
}

/**
 * What somebody typed, turned back into a code we can compare.
 *
 * Spaces, dashes, lower case and a missing or wrong prefix are all fine: the
 * point of this is to work when a person is reading badly-lit handwriting.
 * Returns "" when there is nothing usable, never null.
 */
export function normaliseRecoveryCode(input) {
  const raw = String(input || "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
  if (!raw) return ""

  // Drop a leading prefix of letters that are not in the alphabet's use here —
  // simplest reliable rule: if it starts with a known prefix, remove it.
  const body = raw.replace(/^FCS/, "")
  const digits = body.split("").filter(c => ALPHABET.includes(c))
  if (digits.length < GROUPS * PER_GROUP) return ""

  const code = digits.slice(0, GROUPS * PER_GROUP).join("")
  return `FCS-${code.slice(0, PER_GROUP)}-${code.slice(PER_GROUP)}`
}

/** True when two codes are the same code, whatever they were typed like. */
export function sameRecoveryCode(a, b) {
  const left = normaliseRecoveryCode(a)
  const right = normaliseRecoveryCode(b)
  return Boolean(left) && left === right
}

/** How it is shown to a person: one line, with the reason it matters. */
export const RECOVERY_NOTE =
  "Keep this code. If an email never arrives or you cannot get back in, it is " +
  "how we find your payment without needing the address you signed up with."
