import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import { load } from "../../lib/site-content"
import { collectSiteCss, renderSiteDocument } from "../../lib/site-export"
import * as s from "./HostingNote.module.css"

/**
 * Where a customer's own address has got to — FCS-119.
 * ============================================================================
 * After payment the server makes them name.freecontractorservices.com: a repository, a
 * GitHub Pages site and a DNS record (supabase/functions/provision-site). It takes a minute
 * or two, so this says where it is and, when it is waiting, what to do.
 *
 * ── THE PAGE IS RENDERED HERE, FROM WHAT WAS PUBLISHED ─────────────────────
 * The repository holds a static snapshot of their website. It is made in the browser (the only
 * place the templates' styles can be collected) from the file the server stored, not from the
 * builder's draft, so the snapshot is exactly what the server decided to publish: the plan that
 * was paid for, the sections it covers. Never from the draft.
 *
 * ── EVERY CALL IS SAFE TO REPEAT ───────────────────────────────────────────
 * "Set up", "check again" and "update" are the same request; the server only does what is not
 * already done. So this keeps asking, politely, until it is live or the server says it cannot.
 *
 * Renders nothing once the address is live, or for a page at /their-name (which has no address).
 */

const POLL_MS = 10000
const POLL_MAX = 12

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const res = await fetch(apiUrl("provision-site"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${data?.session?.access_token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { status: res.status, body: await res.json().catch(() => ({})) }
}

const HostingNote = ({ site, autoStart = false, onChange }) => {
  const sub = site?.subdomain || ""
  const initial = site?.hosting?.status || "none" // none | pending | live | failed
  const [phase, setPhase] = React.useState(initial === "live" ? "live" : initial === "pending" ? "pending" : initial === "failed" ? "failed" : "none")
  const [message, setMessage] = React.useState("")
  const [hostname, setHostname] = React.useState(site?.hosting?.hostname || "")
  const polls = React.useRef(0)
  const slow = React.useRef(false)
  const started = React.useRef(false)

  const apply = React.useCallback(
    reply => {
      const { status, body } = reply
      if (status === 200 && body.status === "live") {
        setPhase("live")
        setHostname(body.hostname)
        if (onChange) onChange()
      } else if (status === 200) {
        setPhase("pending")
        setHostname(body.hostname)
        // When GitHub asked us to slow down the server says so in the step it is stuck on: show that, and ask less often.
        const stuck = (body.steps || []).find(st => st.ok === null && st.id === "repo")
        setMessage(stuck ? stuck.detail : "")
        slow.current = Boolean(stuck)
      } else if (status === 402) {
        setPhase("payment")
        setMessage(body.message || "")
      } else if (status === 501) {
        setPhase("waiting")
        setMessage(body.message || "")
      } else {
        setPhase("failed")
        setMessage(body.message || "We could not set up your address just now.")
      }
    },
    [onChange]
  )

  const check = React.useCallback(async () => {
    setPhase(p => (p === "live" ? p : "working"))
    apply(await call({ action: "status", subdomain: sub }).catch(() => ({ status: 0, body: {} })))
  }, [apply, sub])

  const start = React.useCallback(async () => {
    setPhase("working")
    setMessage("")
    /* The server may have done all of this already: paying starts it (the Stripe webhook publishes what was saved before checkout and
       builds the address), so ask first. A browser is only needed when the server has nothing to go on. */
    const first = await call({ action: "status", subdomain: sub }).catch(() => ({ status: 0, body: {} }))
    if (first.status === 200) return apply(first)
    const file = await load(sub)
    if (!file.ok) {
      setPhase("failed")
      setMessage(`We could not read your published website: ${file.reason}`)
      return
    }
    let html = ""
    try {
      html = renderSiteDocument(file.site.content, collectSiteCss(), { plan: file.site.plan })
    } catch {
      setPhase("failed")
      setMessage("We could not prepare your page. Please try again.")
      return
    }
    // The payment can reach us a few seconds after the customer reaches this page: ask again, quietly.
    for (let attempt = 0; attempt < 6; attempt++) {
      const reply = await call({ action: "provision", subdomain: sub, html }).catch(() => ({ status: 0, body: {} }))
      if (reply.status !== 402 || attempt === 5) return apply(reply)
      setPhase("confirming")
      await new Promise(r => setTimeout(r, 4000))
    }
  }, [apply, sub])

  React.useEffect(() => {
    if (autoStart && sub && !started.current && phase !== "live") {
      started.current = true
      start()
    }
  }, [autoStart, sub, phase, start])

  // While it is building, keep asking.
  React.useEffect(() => {
    if (phase !== "pending") return undefined
    if (polls.current >= POLL_MAX) {
      setMessage("It is taking longer than usual. Nothing is lost: check again in a few minutes.")
      return undefined
    }
    const timer = window.setTimeout(() => {
      polls.current += 1
      check()
    }, slow.current ? POLL_MS * 6 : POLL_MS)
    return () => window.clearTimeout(timer)
  }, [phase, check])

  if (!sub || site?.placement === "path" || phase === "live") return null

  const busy = phase === "working" || phase === "confirming"
  const title =
    phase === "pending" || busy
      ? phase === "confirming"
        ? "Confirming your payment…"
        : "Setting up your address…"
      : phase === "waiting"
        ? "Your address is not switched on yet"
        : phase === "payment"
          ? "Your address comes with a paid plan"
          : phase === "failed"
            ? "We could not finish your address"
            : "Your own address is not set up yet"

  return (
    <div className={s.note} data-phase={phase} data-testid="hosting-note" role="status">
      <div className={s.text}>
        <strong>{title}</strong>
        <span>
          {phase === "none"
            ? `Your website is saved. Press the button and we will put it on ${sub}.freecontractorservices.com.`
            : phase === "pending" || busy
              ? message || `${hostname || `${sub}.freecontractorservices.com`} will be live in a minute or two. You do not need to stay on this page.`
              : message}
        </span>
      </div>
      {busy || (phase === "pending" && !message) ? <span className={s.spin} aria-hidden="true" /> : null}
      {!busy && phase !== "payment" ? (
        <button type="button" className={s.button} onClick={phase === "pending" ? check : start} data-testid="hosting-button">
          {phase === "none" ? "Set up my address" : phase === "pending" ? "Check again" : "Try again"}
        </button>
      ) : null}
    </div>
  )
}

export default HostingNote
